/* 回溯 */
func backtrack(choices []int, state, n int, res []int) {
	// 当爬到第 n 阶时，方案数量加 1
	if state == n {
		res[0] = res[0] + 1
	}
	// 遍历所有选择
	for _, choice := range choices {
		// 剪枝：不允许越过第 n 阶
		if state+choice > n {
			continue
		}
		// 尝试：做出选择，更新状态
		backtrack(choices, state+choice, n, res)
		// 回退
	}
}

